parameters.inputSchema:
{
  "type": "object",
  "required": [
    "intencion",
    "confianza"
  ],
  "properties": {
    "intencion": {
      "type": "string",
      "enum": [
        "precio",
        "info",
        "producto",
        "seguimiento",
        "otro"
      ]
    },
    "confianza": {
      "type": "number",
      "description": "0 a 1"
    },
    "respuestaInfo": {
      "type": "string",
      "description": "solo si intencion=info y la tool trajo el dato; si no, vacio"
    },
    "motivo": {
      "type": "string"
    }
  }
}
